import { Component, EventEmitter, Input, Output } from '@angular/core';

@Component({
  selector: 'app-filter',
  templateUrl: './filter.component.html',
  styleUrls: ['./filter.component.css']
})
export class FilterComponent {
  @Input() all: number = 0;
  @Input() inStock: number = 0;
  @Input() outOfstock: number = 0;

  @Output() productSelectedButtonChanged = new EventEmitter<string>();

  selectedFilterRadioButton: string = 'all';

  onProductSelectedButtonChanged() {
    this.productSelectedButtonChanged.emit(this.selectedFilterRadioButton);
  }
}
<div class="filter-container">
  <span>Filter:</span>

  <input
    type="radio"
    name="filter"
    value="all"
    [(ngModel)]="selectedFilterRadioButton"
    (change)="onProductSelectedButtonChanged()">
  <span> {{ 'All (' + all + ')' }} </span>

  <input
    type="radio"
    name="filter"
    value="inStock"
    [(ngModel)]="selectedFilterRadioButton"
    (change)="onProductSelectedButtonChanged()">
  <span> {{ 'In Stock (' + inStock +')' }} </span>

  <input
    type="radio"
    name="filter"
    value="outOfStock"
    [(ngModel)]="selectedFilterRadioButton"
    (change)="onProductSelectedButtonChanged()">
  <span> {{ 'Out Of Stock (' + outOfstock + ')' }} </span>
</div>
